BEGIN;

UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 112" xmlns="http://www.w3.org/2000/svg" font-family="sans-serif"><text x="170" y="18" text-anchor="middle" font-size="11" fill="#8892a4">サーバー</text><rect x="30" y="26" width="280" height="60" rx="6" fill="none" stroke="#2a2f3f" stroke-width="1.3"/><circle cx="55" cy="56" r="12" fill="none" stroke="#6ab08d" stroke-width="1.6"/><text x="55" y="60" text-anchor="middle" font-size="9" fill="#6ab08d">80番</text><text x="55" y="100" text-anchor="middle" font-size="9" fill="#8892a4">開放</text><circle cx="115" cy="56" r="12" fill="none" stroke="#c47070" stroke-width="1.6"/><line x1="107" y1="48" x2="123" y2="64" stroke="#c47070" stroke-width="1.4"/><text x="115" y="60" text-anchor="middle" font-size="9" fill="#c47070">22番</text><text x="115" y="100" text-anchor="middle" font-size="9" fill="#8892a4">遮断</text><circle cx="175" cy="56" r="12" fill="none" stroke="#c47070" stroke-width="1.6"/><line x1="167" y1="48" x2="183" y2="64" stroke="#c47070" stroke-width="1.4"/><text x="175" y="60" text-anchor="middle" font-size="9" fill="#c47070">9999番</text><text x="175" y="100" text-anchor="middle" font-size="9" fill="#8892a4">遮断</text></svg>'), options = '["開いているポートは外部から接続できる入口になるため、使っていない入口は攻撃の糸口になりうるから", "ポートを閉じると、サーバーのディスク容量が自動的に大きく増える仕組みになっているから", "ポートを閉じると、ファイルの所有者が自動的にすべて変更される仕組みになっているから", "ポートを閉じると、CPUの計算速度が自動的に大きく速くなる仕組みになっているから"]'::jsonb WHERE source_ref = 'linux-q142' AND subject_id = (SELECT id FROM public.subjects WHERE slug='linux-basics');

UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 124" xmlns="http://www.w3.org/2000/svg" font-family="sans-serif"><defs><marker id="arrowg" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#6ab08d"/></marker></defs><text x="170" y="16" text-anchor="middle" font-size="11" fill="#8892a4">ファイアウォール（フィルタ）</text><rect x="140" y="34" width="60" height="70" rx="6" fill="none" stroke="#60a5fa" stroke-width="1.4"/><text x="170" y="73" text-anchor="middle" font-size="10" fill="#60a5fa">条件で判定</text><line x1="30" y1="50" x2="140" y2="50" stroke="#6ab08d" stroke-width="1.6"/><line x1="200" y1="50" x2="300" y2="50" stroke="#6ab08d" stroke-width="1.6" marker-end="url(#arrowg)"/><text x="30" y="44" text-anchor="start" font-size="9" fill="#6ab08d">許可された通信</text><line x1="30" y1="90" x2="140" y2="90" stroke="#c47070" stroke-width="1.6"/><line x1="132" y1="82" x2="148" y2="98" stroke="#c47070" stroke-width="1.6"/><text x="30" y="112" text-anchor="start" font-size="9" fill="#c47070">怪しい通信は遮断</text></svg>'), options = '["通信を条件に照らして、通してよいものだけを許可し、それ以外を遮断するフィルタ", "保存されたファイルの中身を読み取り、自動的に要約して短くまとめる仕組み", "サーバーのディスクの空き容量を監視し、自動的に増やしていく仕組み", "登録されているパスワードを、定期的に自動で変更していく仕組み"]'::jsonb WHERE source_ref = 'linux-q143' AND subject_id = (SELECT id FROM public.subjects WHERE slug='linux-basics');

COMMIT;